import {addMonths,due,latest,status,indicators,generatePdf,dashboard,reminders,monthlyProgress,fillEmailTemplate,reportConclusion,buildReportPdf} from './domain.mjs';
const $=s=>document.querySelector(s), KEY='vgp-prototype-v1';
const results=['Bon état','Mauvais état — réparable','Mauvais état — à jeter','Introuvable'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const fmt=d=>d?d.split('-').reverse().join('/'):'Non définie';
const uuid=()=>{if(typeof crypto.randomUUID==='function')return crypto.randomUUID();const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const hex=[...bytes].map(b=>b.toString(16).padStart(2,'0')).join('');return `${hex.slice(0,8)}-${hex.slice(8,12)}-${hex.slice(12,16)}-${hex.slice(16,20)}-${hex.slice(20)}`};
let data, editing=null, selected=null, currentView='material', materialScope='active', ownerFilter=null, selectedOwner=null, storageNeedsRecovery=false, memoryOnly=false;
const demo=()=>({anticipation:30,equipment:[{id:uuid(),identifier:'DEMO-AR-001',designation:'Anneau de retournement · exemple fictif',category:'Anneau de retournement',location:'Atelier A (fictif)',assignment:'Maintenance',months:6,controls:[{id:uuid(),date:'2026-01-15',intervenant:'Intervenant fictif',result:'Bon état',observations:'Exemple à remplacer par vos données.',created:1,attachment:null}]},{id:uuid(),identifier:'DEMO-AR-002',designation:'Anneau à contrôler · exemple fictif',category:'Anneau de retournement',location:'Atelier B (fictif)',assignment:'',months:12,controls:[]}]});
const normalize=value=>String(value??'').trim().toLocaleLowerCase('fr');
const searchKey=value=>normalize(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'');
let storedRaw=null;
try{storedRaw=localStorage.getItem(KEY)}catch{memoryOnly=true;$('#storageNotice').hidden=false}
try{data=storedRaw===null?demo():JSON.parse(storedRaw);if(!valid(data))throw Error('Sauvegarde invalide')}catch{storageNeedsRecovery=true;data={anticipation:30,equipment:[],owners:[]};$('#message').textContent='Sauvegarde locale illisible : aucune donnée existante n’a été remplacée. Importez une sauvegarde valide pour reprendre.';$('#export').disabled=true}
const copyData=value=>typeof globalThis.structuredClone==='function'?globalThis.structuredClone(value):JSON.parse(JSON.stringify(value));

function upgrade(d){d.owners??=[];d.ownerContacts??=[];d.mailTemplates??=defaultMailTemplates();d.verifiers??=[];for(const e of d.equipment)for(const c of e.controls){if(c.intervenant&&!d.verifiers.some(name=>normalize(name)===normalize(c.intervenant)))d.verifiers.push(c.intervenant);c.reportId??=`VGP-${c.date.replaceAll('-','')}-${c.id.toUpperCase()}`;}let next=Math.max(0,...d.equipment.map(e=>Number.isSafeInteger(e.siteId)?e.siteId:0))+1;for(const e of d.equipment)if(!e.siteId)e.siteId=next++;d.nextVgpId=Math.max(d.nextVgpId??1,next);for(const e of d.equipment){for(const k of ['serialNumber','sector','zone','team','owner','comments'])e[k]??='';e.archived??=false;e.archiveHistory??=[];e.pendingArchive??=null;if(e.owner&&!d.owners.includes(e.owner))d.owners.push(e.owner)}return d}
upgrade(data);
function checkDuplicates(){let ok=true;for(const field of ['identifier','serialNumber']){const input=$('#equipmentForm').elements[field];const value=normalize(input.value);const duplicate=value&&data.equipment.some(e=>e.id!==editing&&normalize(e[field])===value);const message=duplicate?(field==='identifier'?'Équipement déjà existant':'Numéro de série déjà existant'):'';input.setCustomValidity(message);input.setAttribute('aria-invalid',String(!!duplicate));$('#'+field+'Error').textContent=message;if(duplicate)ok=false}return ok}
for(const field of ['identifier','serialNumber'])$('#equipmentForm').elements[field].addEventListener('input',checkDuplicates);
function ownerOptions(current=''){const select=$('#equipmentForm').elements.owner;select.innerHTML='<option value="">Non renseigné</option>'+data.owners.map(o=>`<option value="${esc(o)}">${esc(o)}</option>`).join('');select.value=current}
$('#addOwner').onclick=()=>{const name=prompt('Nom du propriétaire à ajouter à la liste :');if(!name?.trim())return;const owner=name.trim();if(owner.length>160){$('#equipmentError').textContent='Le nom du propriétaire est limité à 160 caractères.';return}const existing=data.owners.find(o=>normalize(o)===normalize(owner));if(existing){ownerOptions(existing);return}if(save({...data,owners:[...data.owners,owner]}))ownerOptions(owner)};
function save(next,replace=false){next=upgrade(next);if(storageNeedsRecovery&&!replace){$('#message').textContent='Enregistrement bloqué pour préserver les données existantes. Importez une sauvegarde valide.';return false}try{if(!memoryOnly){try{localStorage.setItem(KEY,JSON.stringify(next))}catch(error){if(error.name!=='SecurityError')throw error;memoryOnly=true;$('#storageNotice').hidden=false}}data=next;storageNeedsRecovery=false;$('#export').disabled=false;render();return true}catch{$('#message').textContent='Enregistrement impossible : stockage plein ou indisponible. Les nouvelles données ne sont pas sauvegardées. Exportez une sauvegarde.';return false}}
let controlContext='normal';
function lastArchive(e){return [...(e.archiveHistory??[])].reverse().find(a=>a.type==='archive')}
function needsScrapControl(e){return e.archived&&archiveReason(e)==='Mis au rebut'&&!lastArchive(e)?.controlId}
function equipmentLabel(e){return `<b class="equipment-name">${esc(e.designation)}</b><small>Numéro interne : ${esc(e.identifier)}</small><small>N° série : ${esc(e.serialNumber)||'Non renseigné'}</small><small>ID VGP : ${e.siteId}</small>`}
function lastResult(e){if(needsScrapControl(e))return 'Mis au rebut — contrôle à compléter';if(e.archived&&archiveReason(e)==='Mis au rebut'){const control=e.controls.find(c=>c.id===lastArchive(e)?.controlId);if(control)return control.result}return latest(e)?.result||'Aucun contrôle'}
function archiveReason(e){return e.archived?[...(e.archiveHistory??[])].reverse().find(a=>a.type==='archive')?.reason||'':''}
function archiveRowClass(e){return !e.archived?'':`archived-row ${archiveReason(e)==='Mis au rebut'?'scrapped-row':archiveReason(e)==='Équipement perdu'?'lost-row':''}`}
function badge(e){let s=status(e,today(),data.anticipation);if(s==='Archivé'){const reason=archiveReason(e);return `<span class="badge archive-badge ${reason==='Mis au rebut'?'scrapped-badge':reason==='Équipement perdu'?'lost-badge':''}">${esc(reason)||'Archivé'}</span>`}if(s==='À définir')return `<button class="badge unknown date-link" data-deadline="${e.id}" aria-label="Définir la date du prochain contrôle de ${esc(e.identifier)}">À définir</button>`;return `<span class="badge ${s==='En retard'?'late':(s==='À venir'||s==='À faire')?'soon':s==='À définir'?'unknown':''}">${s}</span>`}
function resetListFilters(){ownerFilter=null;for(const id of ['search','filter','sectorFilter','zoneFilter','teamFilter','archiveReasonFilter'])$('#'+id).value='';$('#sortBy').value='identifier';updateZoneFilter()}
function updateZoneFilter(){const sector=$('#sectorFilter').value;$('#zoneFilter').disabled=!!sector&&sector!=='B2';if($('#zoneFilter').disabled)$('#zoneFilter').value=''}
function updateEquipmentZones(){const form=$('#equipmentForm');const available=form.elements.sector.value==='B2';form.elements.zone.disabled=!available;if(!available)form.elements.zone.value='';$('#zoneHelp').textContent=available?'Zones disponibles dans B2.':'Sélectionnez B2 pour choisir DMCR ou Yuzer.'}
$('#equipmentForm').elements.sector.addEventListener('change',updateEquipmentZones);
function render(){renderVerifierLists();renderOwners();renderKpi();$('#ownerFilterBar').hidden=ownerFilter===null;$('#ownerFilterLabel').textContent=ownerFilter===''?'Matériel sans propriétaire':`Propriétaire : ${ownerFilter??''}`;const items=data.equipment;const active=items.filter(e=>!e.archived),archived=items.filter(e=>e.archived),scopedItems=materialScope==='archived'?archived:active;$('#activeEquipmentTab').textContent=`Actifs (${active.length})`;$('#archivedEquipmentTab').textContent=`Archivés (${archived.length})`;$('#activeEquipmentTab').setAttribute('aria-pressed',String(materialScope==='active'));$('#archivedEquipmentTab').setAttribute('aria-pressed',String(materialScope==='archived'));
const cards=[['Équipements actifs',active.length,''],['En retard',items.filter(e=>status(e,today(),data.anticipation)==='En retard').length,'En retard'],['À faire',items.filter(e=>status(e,today())==='À faire').length,'À faire'],['Sans contrôle',items.filter(e=>!e.archived&&!latest(e)).length,'without-control'],['Archivés',archived.length,'Archivé']];
$('#stats').innerHTML=cards.map(([label,n,filter])=>`<button class="stat stat-filter" data-status-filter="${filter}" aria-pressed="${filter==='Archivé'?materialScope==='archived':materialScope==='active'&&$('#filter').value===filter}"><small>${label}</small><strong>${n}</strong></button>`).join('');
$('#stats').querySelectorAll('[data-status-filter]').forEach(button=>button.onclick=()=>{resetListFilters();materialScope=button.dataset.statusFilter==='Archivé'?'archived':'active';$('#filter').value=button.dataset.statusFilter;render();$('#listCount').scrollIntoView({block:'nearest'})});
$('#archiveReasonField').hidden=materialScope!=='archived';const q=searchKey($('#search').value),filter=$('#filter').value;
const shown=scopedItems.filter(e=>(!$('#archiveReasonFilter').value||archiveReason(e)===$('#archiveReasonFilter').value)&&(ownerFilter===null||normalize(e.owner)===normalize(ownerFilter))&&searchKey([e.siteId,`ID VGP ${e.siteId}`,e.identifier,e.serialNumber,e.designation,e.category,e.location,e.sector,e.zone,e.team,e.owner,e.assignment].join(' ')).includes(q)&&(!filter||(filter==='without-control'?!e.archived&&!latest(e):status(e,today(),data.anticipation)===filter))&&['sector','zone','team'].every(field=>!$('#'+field+'Filter').value||($('#'+field+'Filter').value==='unassigned'?!e[field]:e[field]===$('#'+field+'Filter').value)));
const sort=$('#sortBy').value;const compare=(a,b)=>String(a??'').localeCompare(String(b??''),'fr',{numeric:true,sensitivity:'base'});shown.sort((a,b)=>{const keys=sort==='sector'?['sector','zone','identifier']:[sort,'identifier'];for(const key of keys){const result=compare(a[key],b[key]);if(result)return result}return 0});
$('#listCount').textContent=`${shown.length} équipement${shown.length!==1?'s':''} affiché${shown.length!==1?'s':''} sur ${scopedItems.length} ${materialScope==='archived'?'archivé(s)':'actif(s)'}${filter?' · '+(filter==='without-control'?'Sans contrôle':filter):''}`;
$('#list').innerHTML=shown.length?`<table><thead><tr><th>Équipement</th><th>Secteur / zone</th><th>Équipe</th><th>Localisation</th><th>Dernier résultat</th><th>Prochaine échéance</th><th></th></tr></thead><tbody>${shown.map(e=>`<tr class="${archiveRowClass(e)}"><td>${equipmentLabel(e)}</td><td>${esc(e.sector)||'—'}<small>${esc(e.zone)||'Zone non renseignée'}</small></td><td>${esc(e.team)||'—'}</td><td>${esc(e.location)||'—'}</td><td>${esc(lastResult(e))}</td><td>${e.archived?'Suivi suspendu':fmt(due(e))}<small>${badge(e)}</small></td><td><button class="secondary" data-open="${e.id}">Ouvrir</button></td></tr>`).join('')}</tbody></table>`:'<p class="empty">Aucun équipement correspondant.</p>'}
$('#activeEquipmentTab').onclick=()=>{materialScope='active';resetListFilters();render()};$('#archivedEquipmentTab').onclick=()=>{materialScope='archived';resetListFilters();render()};
$('#resetFilters').onclick=()=>{resetListFilters();render()};
for(const id of ['sectorFilter','zoneFilter','teamFilter','sortBy','archiveReasonFilter'])$('#'+id).onchange=()=>{if(id==='sectorFilter')updateZoneFilter();render()};
function setView(view,owner=null){currentView=view;ownerFilter=owner;$('#materialView').hidden=view!=='material';$('#ownersView').hidden=view!=='owners';$('#kpiView').hidden=view!=='kpi';$('#containerMaterialView').hidden=view!=='containerMaterial';$('#containerKpiView').hidden=view!=='containerKpi';$('#mailSettingsView').hidden=view!=='mailSettings';$('#reportSettingsView').hidden=view!=='reportSettings';document.querySelectorAll('[data-view]').forEach(button=>{if(button.dataset.view===view)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current')});selectedOwner=null;if(view==='material'){materialScope='active';resetListFilters();ownerFilter=owner}render();if($('#navigation').open)$('#navigation').close();if($('#settingsMenu').open)$('#settingsMenu').close();if(view==='mailSettings')renderMailSettings();if(view==='reportSettings')renderReportSettings();$('#'+({owners:'ownersTitle',material:'materialTitle',kpi:'kpiTitle',containerMaterial:'containerMaterialTitle',containerKpi:'containerKpiTitle',mailSettings:'mailSettingsTitle',reportSettings:'reportSettingsTitle'}[view])).focus()}
function renderKpi(){renderMonthlyKpi();const k=dashboard(data.equipment,today(),data.anticipation);const percent=k.percent===null?'—':`${k.percent} %`;const bars=(rows,total)=>rows.map(({label,count,tone='',kind})=>`<button class="metric-row metric-link" data-kpi-list="${esc(kind||'result:'+label)}"><div class="metric-label"><span>${esc(label)}</span><b>${count}</b></div><div class="metric-track"><span class="${tone}" style="width:${total?count/total*100:0}%"></span></div></button>`).join('');
$('#kpiVisual').innerHTML=`<section class="panel coverage-panel"><div><p class="eyebrow">COUVERTURE DU PARC VGP ACTIF</p><h2>Équipements contrôlés</h2><p>Au moins un contrôle enregistré, quelle que soit son ancienneté ou son résultat.</p><div class="coverage-legend"><button class="legend-link" data-kpi-list="controlled"><i class="dot green"></i><b>${k.controlled}</b> contrôlé(s) · ${k.percent===null?'—':k.percent+' %'}</button><button class="legend-link" data-kpi-list="missing"><i class="dot grey"></i><b>${k.missing}</b> jamais contrôlé(s) · ${k.percent===null?'—':100-k.percent+' %'}</button></div><p class="foot">${k.total} équipement(s) actif(s) · ${k.archived} archivé(s) exclus du pourcentage.</p></div><button class="donut" data-kpi-list="controlled" style="--percentage:${k.percent??0}%" aria-label="Voir les équipements contrôlés : ${k.total?`${k.controlled} équipements contrôlés sur ${k.total}, soit ${percent}`:'Aucun équipement actif, pourcentage non calculable'}"><div><strong id="kpi-percent">${percent}</strong><span>${k.total?'du parc contrôlé':'Aucun équipement actif'}</span></div></button></section><section class="stats kpi-cards"><button class="stat kpi-clickable" data-kpi-list="active"><small>Parc actif</small><strong>${k.total}</strong><p class="foot">Équipements à suivre</p></button><button class="stat kpi-clickable" data-kpi-list="missing"><small>Jamais contrôlés</small><strong>${k.missing}</strong><p class="foot">Aucun contrôle enregistré</p></button><button class="stat alert-stat kpi-clickable" data-kpi-list="todo"><small>Contrôles à faire</small><strong id="kpi-todo">${k.soon+k.overdue}</strong><p class="foot">À moins d’un mois + en retard</p></button><button class="stat kpi-clickable" data-kpi-list="history"><small>Contrôles réalisés</small><strong id="kpi-performed">${k.performed}</strong><p class="foot">Tout l’historique, archives comprises</p></button></section><div class="kpi-grid"><section class="panel"><h2>Où en sont les échéances ?</h2><p class="foot">Une seule catégorie par équipement actif.</p>${bars([{kind:'undefined',label:'Échéance à définir',count:k.undefinedCount,tone:'muted'},{kind:'overdue',label:'En retard',count:k.overdue,tone:'red'},{kind:'soon',label:'À faire — échéance dans un mois ou moins',count:k.soon,tone:'amber'},{kind:'planned',label:'Planifiés — échéance à plus d’un mois',count:k.planned,tone:'green'}],k.total)}<button class="secondary" id="kpiOpenMaterial">Voir le matériel VGP</button></section><section class="panel"><h2>Résultat du dernier contrôle</h2><p class="foot">${k.controlled} équipement(s) contrôlé(s) actifs. Résultats déclarés, sans certification automatique.</p>${bars(k.results.map((r,i)=>({...r,tone:['green','amber','red','muted'][i]})),k.controlled)}</section><section class="panel sector-panel"><h2>Avancement par secteur</h2><p class="foot">Équipements avec au moins un contrôle / total actif du secteur.</p>${k.sectors.map(row=>`<button class="sector-progress" data-kpi-sector="${row.sector}"><div class="metric-label"><span>${row.sector||'Secteur non renseigné'}</span><b>${row.controlled} / ${row.total} · ${row.total?Math.round(row.controlled/row.total*100)+' %':'—'}</b></div><div class="metric-track"><span class="green" style="width:${row.total?row.controlled/row.total*100:0}%"></span></div></button>`).join('')}</section><section class="panel"><h2>Actions réalisées</h2><button class="action-total legend-link" id="kpi-actions" data-kpi-list="history">${k.performed}</button><p>Une action correspond ici à un contrôle enregistré.</p><p class="foot">Cet indicateur reprend tout l’historique. Les réparations et mises au rebut ne sont pas comptées comme des actions réalisées.</p></section></div>`;
$('#kpiVisual').querySelectorAll('[data-kpi-list]').forEach(button=>button.onclick=()=>openKpiList(button.dataset.kpiList));$('#kpiOpenMaterial').onclick=()=>setView('material');$('#kpiVisual').querySelectorAll('[data-kpi-sector]').forEach(button=>button.onclick=()=>{setView('material');$('#sectorFilter').value=button.dataset.kpiSector||'unassigned';updateZoneFilter();render()})}
function openKpiList(kind){const active=data.equipment.filter(e=>!e.archived),history=kind==='history';const statusKinds={undefined:'À définir',overdue:'En retard',soon:'À faire',planned:'Planifié'};const titles={active:'Parc actif',controlled:'Équipements contrôlés',missing:'Équipements jamais contrôlés',todo:'Contrôles à faire ou en retard',history:'Contrôles réalisés — historique complet',...Object.fromEntries(Object.entries(statusKinds).map(([k,v])=>[k,v]))};const items=history?data.equipment.flatMap(e=>e.controls.map(c=>({e,c}))):active.filter(e=>kind==='active'||kind==='controlled'&&latest(e)||kind==='missing'&&!latest(e)||kind==='todo'&&['À faire','En retard'].includes(status(e,today()))||statusKinds[kind]&&status(e,today())===statusKinds[kind]||kind.startsWith('result:')&&latest(e)?.result===kind.slice(7)).map(e=>({e}));$('#kpiListTitle').textContent=titles[kind]||'Dernier résultat : '+kind.slice(7);$('#kpiListContent').innerHTML=`<p>${items.length} ${history?'contrôle(s) enregistré(s), archives comprises':'équipement(s) actif(s)'}</p><div class="owner-equipment-list">${items.length?`<table><thead><tr><th>Équipement</th><th>${history?'Date du contrôle':'Échéance'}</th><th>${history?'Résultat':'État'}</th><th></th></tr></thead><tbody>${items.map(({e,c})=>`<tr class="${archiveRowClass(e)}"><td>${equipmentLabel(e)}${e.archived?badge(e):''}</td><td>${fmt(history?c.date:due(e))}</td><td>${history?esc(c.result):badge(e)}</td><td><button class="secondary" data-kpi-open-equipment="${e.id}">Ouvrir la fiche</button></td></tr>`).join('')}</tbody></table>`:'<p class="empty">Aucun élément dans cette liste.</p>'}</div>`;$('#kpiListContent').querySelectorAll('[data-kpi-open-equipment]').forEach(button=>button.onclick=()=>{$('#kpiListDialog').close();showDetail(button.dataset.kpiOpenEquipment)});$('#kpiListDialog').showModal()}
let monthlyYear=Number(today().slice(0,4));
function renderMonthlyKpi(){const report=monthlyProgress(data.equipment,monthlyYear,today()),names=['Jan','Fév','Mar','Avr','Mai','Juin','Juil','Août','Sep','Oct','Nov','Déc'];$('#monthlyYear').value=monthlyYear;const points=report.months.map((m,i)=>m.percent===null?null:{x:55+i*65,y:220-m.percent*1.8,m}).filter(Boolean);const segments=[];let current=[];report.months.forEach((m,i)=>{if(m.percent===null){if(current.length)segments.push(current);current=[]}else current.push(`${55+i*65},${220-m.percent*1.8}`)});if(current.length)segments.push(current);
$('#monthlyChart').innerHTML=`<svg viewBox="0 0 810 265" role="img" aria-label="Pourcentage des contrôles réalisés par mois, année ${monthlyYear}">${[0,25,50,75,100].map(n=>`<line x1="45" x2="790" y1="${220-n*1.8}" y2="${220-n*1.8}" stroke="#dfe8e2"/><text x="3" y="${225-n*1.8}" fill="#5e7668" font-size="11">${n}%</text>`).join('')}${segments.map(points=>`<polyline fill="none" stroke="#28775b" stroke-width="3" points="${points.join(' ')}"/>`).join('')}${points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="5" fill="#28775b"/><text x="${p.x}" y="${p.y-12}" text-anchor="middle" font-size="12" fill="#204838">${p.m.percent}%</text>`).join('')}${names.map((name,i)=>`<text x="${55+i*65}" y="250" text-anchor="middle" font-size="12" fill="#5e7668">${name}</text>`).join('')}</svg>`;
$('#monthlyCards').innerHTML=report.months.map((m,i)=>`<article class="month-card"><h3>${names[i]}</h3><strong>${m.percent===null?'—':m.percent+' %'}</strong><p>${m.done} / ${m.total} réalisé(s)</p><button class="secondary" data-month-open="${m.month}" ${!m.remaining?'disabled':''}>${m.total?100-m.percent+' %':'—'} non réalisés</button><small>${m.overdue} en retard</small></article>`).join('');$('#monthlyHistoryNote').textContent=report.unknownHistory?`${report.unknownHistory} contrôle(s) historique(s) sans date prévue connue : exclus de ce calcul, car leur ancien planning ne peut pas être reconstitué.`:'Les échéances des contrôles réalisés sont conservées pour suivre les mois passés.';$('#monthlyCards').querySelectorAll('[data-month-open]').forEach(button=>button.onclick=()=>openMonthlyRemaining(Number(button.dataset.monthOpen)))}
function openMonthlyRemaining(month){const m=monthlyProgress(data.equipment,monthlyYear,today()).months[month-1],name=new Date(Date.UTC(monthlyYear,month-1,1)).toLocaleDateString('fr-FR',{month:'long',year:'numeric',timeZone:'UTC'});$('#monthlyRemainingTitle').textContent=`Contrôles non réalisés — ${name}`;$('#monthlyRemainingList').innerHTML=`<p>${m.remaining} non réalisé(s), dont ${m.overdue} en retard. Une échéance future n’est pas un retard.</p><div class="owner-equipment-list"><table><thead><tr><th>Équipement</th><th>Date prévue</th><th>État</th><th></th></tr></thead><tbody>${m.entries.filter(e=>!e.done).map(e=>`<tr><td><b>${esc(e.identifier)}</b><small>${esc(e.name)}</small></td><td>${fmt(e.date)}</td><td>${e.overdue?'<span class="badge late">En retard</span>':'<span class="badge">Échéance non dépassée</span>'}</td><td><button class="secondary" data-month-equipment="${e.equipmentId}">Ouvrir la fiche</button></td></tr>`).join('')}</tbody></table></div>`;$('#monthlyRemainingList').querySelectorAll('[data-month-equipment]').forEach(button=>button.onclick=()=>{$('#monthlyRemainingDialog').close();showDetail(button.dataset.monthEquipment)});$('#monthlyRemainingDialog').showModal()}
$('#monthlyYear').onchange=ev=>{const year=Number(ev.target.value);if(!Number.isInteger(year)||year<1900||year>9999){ev.target.value=monthlyYear;return}monthlyYear=year;renderMonthlyKpi()};
function openOwner(owner){selectedOwner=owner;renderOwners();$('#ownerProfileName').focus()}
function renderOwners(){const owners=[...new Map([...data.owners,...data.equipment.map(e=>e.owner).filter(Boolean)].map(o=>[normalize(o),o])).values()].sort((a,b)=>a.localeCompare(b,'fr'));const cards=owners.map(owner=>({owner,items:data.equipment.filter(e=>normalize(e.owner)===normalize(owner))}));const unassigned=data.equipment.filter(e=>!e.owner);if(unassigned.length)cards.push({owner:'',items:unassigned});$('#ownersList').hidden=selectedOwner!==null;$('#ownerProfile').hidden=selectedOwner===null;$('#createOwner').hidden=selectedOwner!==null;if(selectedOwner===null)$('#ownerProfile').innerHTML='';
$('#ownersList').innerHTML=cards.length?cards.map(({owner,items},index)=>`<article class="owner-card" data-owner-card="${index}"><h2>${esc(owner)||'Sans propriétaire'}</h2><p><strong>${items.filter(e=>!e.archived).length}</strong> équipement(s) actif(s)<br>${items.filter(e=>e.archived).length} archivé(s)</p><button class="secondary" data-owner-index="${index}">${owner?'Ouvrir la fiche':'Voir le matériel'}<span class="sr-only"> de ${esc(owner)||'Sans propriétaire'}</span></button></article>`).join(''):'<div class="panel empty">Aucun propriétaire enregistré. Ajoutez un propriétaire puis associez-le à un équipement depuis sa fiche.</div>';$('#ownersList').querySelectorAll('[data-owner-index]').forEach(button=>button.onclick=()=>{const owner=cards[Number(button.dataset.ownerIndex)].owner;if(owner)openOwner(owner);else setView('material','')});
$('#ownersList').querySelectorAll('[data-owner-card]').forEach(card=>card.onclick=ev=>{if(ev.target.closest('button'))return;const owner=cards[Number(card.dataset.ownerCard)].owner;if(owner)openOwner(owner);else setView('material','')});
if(selectedOwner!==null){const items=data.equipment.filter(e=>normalize(e.owner)===normalize(selectedOwner));$('#ownerProfile').innerHTML=`<section class="panel"><div class="toolbar"><div><p class="eyebrow">VGP · FICHE EMPLOYÉ / PROPRIÉTAIRE</p><h2 id="ownerProfileName" tabindex="-1">${esc(selectedOwner)}</h2></div><button class="secondary" id="backToOwners">Retour aux propriétaires</button><button id="associateEquipment">+ Associer un équipement existant</button></div><p>${items.filter(e=>!e.archived).length} équipement(s) actif(s) · ${items.filter(e=>e.archived).length} archivé(s)</p>${ownerContactHtml(selectedOwner)}<div class="owner-equipment-list">${items.length?`<table><thead><tr><th>Matériel</th><th>Secteur / zone</th><th>Équipe</th><th>Échéance</th><th></th></tr></thead><tbody>${items.map(e=>`<tr class="${archiveRowClass(e)}"><td>${equipmentLabel(e)}</td><td>${esc(e.sector)||'—'}<small>${esc(e.zone)}</small></td><td>${esc(e.team)||'—'}</td><td>${badge(e)}<small>${e.archived?'Suivi suspendu':fmt(due(e))}</small></td><td><button class="secondary" data-open="${e.id}">Ouvrir</button></td></tr>`).join('')}</tbody></table>`:'<p class="empty">Aucun équipement associé à cette personne.</p>'}</div>${ownerReminderHtml(items)}</section>`;$('#ownerContactForm').onsubmit=saveOwnerContact;$('#ownerProfile').querySelectorAll('[data-reminder-equipment]').forEach(button=>button.onclick=()=>previewReminder(button.dataset.reminderEquipment,button.dataset.reminderKind));$('#backToOwners').onclick=()=>{selectedOwner=null;renderOwners();$('#ownersTitle').focus()};$('#associateEquipment').onclick=()=>{$('#associationSearch').value='';$('#associationError').textContent='';$('#associateOwner').textContent=`Associer du matériel à ${selectedOwner}`;renderAssociationList();$('#associateDialog').showModal()}}}
function validEmail(email){return email.length<=254&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)}
function ownerContactHtml(owner){const email=data.ownerContacts.find(c=>normalize(c.owner)===normalize(owner))?.email||'';return `<form id="ownerContactForm" class="owner-contact"><label>Adresse e-mail<input name="email" type="email" maxlength="254" value="${esc(email)}" autocomplete="email" placeholder="prenom.nom@entreprise.fr"></label><button class="secondary">Enregistrer l’adresse</button><p id="ownerContactError" class="error" role="alert"></p></form>`}
function saveOwnerContact(ev){ev.preventDefault();const email=new FormData(ev.target).get('email').trim();if(email&&!validEmail(email)){$('#ownerContactError').textContent='Renseignez une adresse e-mail valide.';return}const next=copyData(data);const contact=next.ownerContacts.find(c=>normalize(c.owner)===normalize(selectedOwner));if(contact)contact.email=email;else next.ownerContacts.push({owner:selectedOwner,email});if(save(next)){$('#message').textContent=`Adresse e-mail enregistrée${memoryOnly?' pour cette session uniquement':''}.`}else $('#ownerContactError').textContent=$('#message').textContent}
function ownerReminderHtml(items){const rows=items.flatMap(e=>reminders(e).map(r=>({...r,e}))).sort((a,b)=>a.date.localeCompare(b.date)||a.e.identifier.localeCompare(b.e.identifier,'fr'));return `<section class="owner-reminders"><h3>Rappels par e-mail — prévisualisation</h3><aside>Aucun e-mail n’est envoyé actuellement. L’envoi automatique nécessite un serveur et une connexion au service de messagerie. Le message du jour de l’échéance contient une consigne interne de suspension d’usage, à valider avec votre entreprise.</aside><p class="foot">Calendrier recalculé après chaque contrôle ou réaffectation. Les archives sont exclues. « Un mois » signifie un mois calendaire ; les autres délais sont de 14 et 7 jours.</p><div class="owner-equipment-list">${rows.length?`<table><thead><tr><th>Date prévue</th><th>Équipement</th><th>Rappel</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${fmt(r.date)}<small>${r.date<today()?'Date passée — aucun envoi':r.date===today()?'Prévu aujourd’hui — aucun envoi':'À venir — aucun envoi'}</small></td><td><b>${esc(r.e.identifier)}</b><small>Échéance : ${fmt(r.deadline)}</small></td><td>${r.label}</td><td><button class="secondary" data-reminder-equipment="${r.equipmentId}" data-reminder-kind="${r.kind}">Voir le message</button></td></tr>`).join('')}</tbody></table>`:'<p class="empty">Aucun rappel : aucun équipement actif avec une échéance définie.</p>'}</div></section>`}
function previewReminder(id,kind){const e=data.equipment.find(e=>e.id===id),r=reminders(e).find(r=>r.kind===kind);if(!r)return;const email=data.ownerContacts.find(c=>normalize(c.owner)===normalize(e.owner))?.email||'',template=data.mailTemplates.find(t=>t.kind===kind),values=mailValues(e);$('#emailPreviewMeta').textContent=`Date prévue : ${fmt(r.date)} · Destinataire : ${email||'Adresse e-mail à renseigner'}`;$('#emailPreviewSubject').textContent=fillEmailTemplate(template.subject,values);$('#emailPreviewBody').value=fillEmailTemplate(template.body,values)+'\n\nPRÉVISUALISATION DU PROTOTYPE : ce message n’a pas été envoyé.';$('#emailPreview').showModal()}
function defaultMailTemplates(){return ['month','twoWeeks','week','deadline'].map(kind=>({kind,subject:(kind==='deadline'?'Échéance atteinte — suspension d’utilisation':kind==='month'?'Contrôle à prévoir':'Matériel à apporter pour contrôle')+' : {{numero_interne}}',body:'Bonjour {{nom_proprietaire}},\n\nL’équipement {{nom_equipement}} (numéro interne {{numero_interne}}, ID VGP {{id_vgp}}) doit être contrôlé avant le {{date_controle}}.\n\n'+(kind==='deadline'?"Selon la consigne interne proposée, cet équipement ne doit plus être utilisé avant vérification et autorisation selon la procédure de l’entreprise. Cette consigne reste à valider ; elle n’est pas présentée comme une règle réglementaire.":kind==='month'?'Merci de prévoir son contrôle avant cette date.':'Merci d’apporter le matériel pour permettre son contrôle. Le lieu et les modalités seront précisés par l’entreprise.')+'\n\nMétrologie — suivi VGP'}))}
function mailValues(e){return {nom_equipement:e.designation||'Nom à renseigner',numero_interne:e.identifier||'Numéro à renseigner',id_vgp:e.siteId??'—',nom_proprietaire:e.owner||'Propriétaire à renseigner',date_controle:fmt(due(e)),secteur:e.sector||'Non renseigné',zone:e.zone||'Non renseignée'}}
function validTemplates(templates){return Array.isArray(templates)&&templates.length===4&&new Set(templates.map(t=>t?.kind)).size===4&&templates.every(t=>t&&['month','twoWeeks','week','deadline'].includes(t.kind)&&typeof t.subject==='string'&&t.subject.trim()&&t.subject.length<=300&&typeof t.body==='string'&&t.body.trim()&&t.body.length<=10000)}
function renderMailSettings(){$('#mailSampleEquipment').innerHTML=data.equipment.filter(e=>!e.archived).map(e=>`<option value="${e.id}">${esc(e.identifier)} — ${esc(e.designation)}</option>`).join('')||'<option value="">Aucun matériel actif</option>';loadMailTemplate()}
function loadMailTemplate(){const template=data.mailTemplates.find(t=>t.kind===$('#mailTemplateKind').value);$('#mailSubject').value=template.subject;$('#mailBody').value=template.body;$('#mailTemplateError').textContent='';$('#mailTemplateSaved').textContent='';updateMailPreview()}
function updateMailPreview(){const e=data.equipment.find(e=>e.id===$('#mailSampleEquipment').value);if(!e){$('#mailSettingsPreview').textContent='Ajoutez un équipement actif pour prévisualiser les remplacements.';return}const values=mailValues(e),email=data.ownerContacts.find(c=>normalize(c.owner)===normalize(e.owner))?.email||'Adresse à renseigner';$('#mailSettingsPreview').textContent=`Destinataire : ${email}\nObjet : ${fillEmailTemplate($('#mailSubject').value,values)}\n\n${fillEmailTemplate($('#mailBody').value,values)}\n\nSIMULATION : aucun e-mail envoyé.`}
$('#mailTemplateKind').onchange=loadMailTemplate;$('#mailSampleEquipment').onchange=updateMailPreview;$('#mailSubject').oninput=$('#mailBody').oninput=()=>{$('#mailTemplateSaved').textContent='Modifications non enregistrées.';updateMailPreview()};
$('#mailTemplateForm').onsubmit=ev=>{ev.preventDefault();const next=copyData(data),template=next.mailTemplates.find(t=>t.kind===$('#mailTemplateKind').value);const subject=$('#mailSubject').value.trim(),body=$('#mailBody').value.trim();const tokens=[...subject.matchAll(/\{\{([^{}]*)\}\}/g),...body.matchAll(/\{\{([^{}]*)\}\}/g)].map(m=>m[1].trim()),allowed=['nom_equipement','numero_interne','id_vgp','nom_proprietaire','date_controle','secteur','zone'];const unknown=tokens.filter(t=>!allowed.includes(t));if(unknown.length){$('#mailTemplateError').textContent='Champs inconnus : '+unknown.join(', ');return}template.subject=subject;template.body=body;if(!validTemplates(next.mailTemplates)){$('#mailTemplateError').textContent='Renseignez un objet et un message valides.';return}if(save(next)){$('#mailTemplateError').textContent='';$('#mailTemplateSaved').textContent=`Modèle enregistré${memoryOnly?' pour cette session uniquement':''}.`;updateMailPreview()}else $('#mailTemplateError').textContent=$('#message').textContent};
$('#settingsToggle').onclick=()=>{$('#settingsToggle').setAttribute('aria-expanded','true');$('#settingsMenu').showModal()};$('#settingsMenu').addEventListener('close',()=>$('#settingsToggle').setAttribute('aria-expanded','false'));$('#settingsMenu').addEventListener('click',ev=>{if(ev.target===$('#settingsMenu')){const r=ev.target.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)ev.target.close()}});

function renderAssociationList(){const q=normalize($('#associationSearch').value);const items=data.equipment.filter(e=>!e.archived&&normalize([e.identifier,e.designation,e.serialNumber,e.siteId,e.sector,e.zone].join(' ')).includes(q));$('#associationList').innerHTML=items.length?`<table><thead><tr><th>Équipement</th><th>Propriétaire actuel</th><th></th></tr></thead><tbody>${items.map(e=>`<tr><td>${equipmentLabel(e)}</td><td>${esc(e.owner)||'Non renseigné'}</td><td><button class="secondary" data-associate="${e.id}" ${normalize(e.owner)===normalize(selectedOwner)?'disabled':''}>${normalize(e.owner)===normalize(selectedOwner)?'Déjà associé':'Associer'}</button></td></tr>`).join('')}</tbody></table>`:'<p class="empty">Aucun équipement actif correspondant.</p>';$('#associationList').querySelectorAll('[data-associate]').forEach(button=>button.onclick=()=>{const e=data.equipment.find(e=>e.id===button.dataset.associate);if(!e||e.archived||selectedOwner===null)return;if(e.owner&&normalize(e.owner)!==normalize(selectedOwner)&&!confirm(`L’équipement ${e.identifier} est associé à ${e.owner}. Le réaffecter à ${selectedOwner} ?`))return;const next=copyData(data);next.equipment.find(item=>item.id===e.id).owner=selectedOwner;if(save(next)){$('#associateDialog').close();$('#message').textContent=`Équipement ${e.identifier} associé à ${selectedOwner}${memoryOnly?' pour cette session uniquement':''}.`;$('#ownerProfileName').focus()}else $('#associationError').textContent=$('#message').textContent})}
$('#associationSearch').oninput=renderAssociationList;
$('#menuToggle').onclick=()=>{$('#menuToggle').setAttribute('aria-expanded','true');$('#navigation').showModal()};
$('#navigation').addEventListener('close',()=>$('#menuToggle').setAttribute('aria-expanded','false'));
$('#navigation').addEventListener('click',ev=>{if(ev.target===$('#navigation')){const rect=ev.target.getBoundingClientRect();if(ev.clientX<rect.left||ev.clientX>rect.right||ev.clientY<rect.top||ev.clientY>rect.bottom)ev.target.close()}});
document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>setView(button.dataset.view));
$('#clearOwnerFilter').onclick=()=>setView('material');
$('#createOwner').onclick=()=>$('#addOwner').click();
let verifierListSequence=0;
function renderVerifierLists(){document.querySelectorAll('[data-verifier-list]').forEach(list=>list.innerHTML=data.verifiers.map(name=>`<option value="${esc(name)}"></option>`).join(''))}
function verifierInput(required){const listId=`verifiers-${++verifierListSequence}`;return `<label>Vérificateur ${required?'*':''}<input name="intervenant" list="${listId}" maxlength="160" ${required?'required':''} placeholder="Choisir ou ajouter un vérificateur"><datalist id="${listId}" data-verifier-list>${data.verifiers.map(name=>`<option value="${esc(name)}"></option>`).join('')}</datalist><button type="button" class="secondary" data-add-verifier>+ Ajouter un vérificateur</button><small>Choisissez un nom dans la liste ou saisissez un nouveau nom.</small></label>`}
function equipmentSnapshot(e){return Object.fromEntries(['siteId','identifier','serialNumber','designation','location','sector','zone','team','owner','months','comments'].map(key=>[key,e[key]??'']))}
function fields(required){return `<div class="fields"><label>Date du contrôle ${required?'*':''}<input type="date" name="date" max="${today()}" ${required?'required':''}></label>${verifierInput(required)}<label>Résultat<select name="result"><option value="">Choisir un résultat</option>${results.map(r=>`<option>${r}</option>`).join('')}</select></label><label>Justificatif (PDF ou image, 1 Mo maximum)<input type="file" name="attachment" accept="application/pdf,image/png,image/jpeg,image/webp"></label><label class="wide">Observations<textarea name="observations" maxlength="5000"></textarea></label></div>`}
$('#initialFields').innerHTML=fields(false);$('#controlFields').innerHTML=fields(true);
async function readControl(form,required){const f=new FormData(form),date=f.get('date'),file=f.get('attachment');if(!date){if(required||f.get('intervenant')||f.get('result')||f.get('observations')||file?.size)throw Error('Renseignez la date du contrôle ou laissez tous ses champs vides.');return null}if(date>today())throw Error('Un contrôle réalisé ne peut pas être daté dans le futur.');if(f.get('intervenant').trim().length>160)throw Error('Le nom du vérificateur est limité à 160 caractères.');if(!f.get('result')||!f.get('intervenant').trim())throw Error('Renseignez le résultat et le vérificateur (intervenant).');let attachment=null;if(file?.size){if(file.size>1024*1024)throw Error('Le justificatif dépasse 1 Mo.');if(!['application/pdf','image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Utilisez un PDF ou une image PNG, JPEG ou WebP.');const url=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Lecture du fichier impossible.'));r.readAsDataURL(file)});attachment={name:file.name,type:file.type,url}}const id=uuid();return {id,reportId:`VGP-${date.replaceAll('-','')}-${id.toUpperCase()}`,date,intervenant:f.get('intervenant').trim(),result:f.get('result'),observations:f.get('observations'),attachment,created:Date.now()}}
function edit(id=null){editing=id;const e=data.equipment.find(e=>e.id===id);$('#equipmentForm').reset();$('#equipmentError').textContent='';$('#initial').hidden=!!e;$('#editorTitle').textContent=e?'Modifier l’équipement':'Ajouter un équipement';ownerOptions(e?.owner);if(e)for(const k of ['identifier','serialNumber','sector','zone','team','designation','location','months'])$('#equipmentForm').elements[k].value=e[k];$('#equipmentForm').elements.manualNextControlDate.value=e?.manualNextControlDate&&(e.manualControlId??null)===(latest(e)?.id??null)?e.manualNextControlDate:'';$('#manualDateFields').hidden=!$('#equipmentForm').elements.manualNextControlDate.value;updateEquipmentZones();checkDuplicates();$('#editor').showModal()}
$('#add').onclick=()=>edit();$('#toggleManualDate').onclick=()=>{const fields=$('#manualDateFields');fields.hidden=!fields.hidden;if(fields.hidden)$('#equipmentForm').elements.manualNextControlDate.value='';else $('#equipmentForm').elements.manualNextControlDate.focus()};
$('#equipmentForm').onsubmit=async ev=>{ev.preventDefault();const button=ev.target.querySelector('button[type=submit],button:not([type])');if(button.disabled)return;button.disabled=true;try{const f=new FormData(ev.target),old=data.equipment.find(e=>e.id===editing),identifier=f.get('identifier').trim();if(!identifier||!f.get('designation').trim())throw Error('Le numéro interne et le nom sont obligatoires.');if(!checkDuplicates())throw Error('Corrigez les numéros déjà existants.');const control=old?null:await readControl(ev.target,false);const createdDate=old?.createdDate??today(),automaticFirst=old&&!old.createdDate?(old.firstControlDate??addMonths(createdDate,f.get('months'))):addMonths(createdDate,f.get('months')),manual=f.get('manualNextControlDate')||null;const e={comments:old?(old.comments??''):`Mise en service le ${fmt(createdDate)}`,createdDate,manualNextControlDate:manual,manualControlId:(old?latest(old):control)?.id??null,id:editing||uuid(),siteId:old?.siteId??data.nextVgpId,identifier,serialNumber:f.get('serialNumber').trim(),sector:f.get('sector'),zone:f.get('sector')==='B2'?f.get('zone'):'',team:f.get('team'),owner:f.get('owner'),designation:f.get('designation').trim(),category:old?.category??'',location:f.get('location').trim(),assignment:old?.assignment??'',months:Number(f.get('months')),archived:old?.archived??false,archiveHistory:old?.archiveHistory??[],pendingArchive:old?.pendingArchive??null,scheduledControl:old?(old.scheduledControl?{...old.scheduledControl,date:manual||automaticFirst}:null):(control||manual)?null:{id:uuid(),date:automaticFirst},firstControlDate:(old?old.controls.length:!!control)?(old?.firstControlDate??null):automaticFirst,controls:old?old.controls:control?[control]:[]};if(control)control.equipmentSnapshot=equipmentSnapshot(e);if(!checkDuplicates())throw Error('Corrigez les numéros déjà existants.');const next=copyData(data);if(old)next.equipment[next.equipment.findIndex(x=>x.id===editing)]=e;else{next.equipment.push(e);next.nextVgpId=e.siteId+1}if(save(next)){$('#editor').close();if(old)showDetail(e.id);else{setView('material');$('#message').textContent=`Équipement ${e.identifier} créé et enregistré${memoryOnly?' pour cette session uniquement':''}. ${control?'Dernier contrôle enregistré.':'Premier contrôle à faire le '+fmt(due(e))+'.'}`}}else{$('#equipmentError').textContent=$('#message').textContent}}catch(e){$('#equipmentError').textContent=e.message}finally{button.disabled=false}};
function showDetail(id){selected=id;const e=data.equipment.find(x=>x.id===id);$('#detailTitle').textContent=`${e.identifier} · ${e.designation}`;$('#detailContent').innerHTML=`<div class="equipment-tabs" role="group" aria-label="Onglets de la fiche équipement"><button id="overviewTab" aria-pressed="true">Fiche</button><button id="commentsTab" aria-pressed="false">Commentaires</button></div><div id="equipmentOverview"><p><b>ID VGP : ${e.siteId}</b> · Identifiant du site, attribué automatiquement.<br>${esc(e.location)||'Localisation non renseignée'}<br>Numéro de série : ${esc(e.serialNumber)||'Non renseigné'}<br>Secteur : ${esc(e.sector)||'Non renseigné'} · Zone : ${esc(e.zone)||'Non renseignée'} · Équipe : ${esc(e.team)||'Non renseignée'}<br>Propriétaire : ${esc(e.owner)||'Non renseigné'}</p><p>${e.archived?'Archivé — suivi suspendu. Dernière échéance calculée':'Prochaine échéance'} : <b>${fmt(due(e))}</b> ${badge(e)}<br>Périodicité choisie : ${e.months} mois depuis le dernier contrôle. À valider par votre entreprise.</p><div class="actions">${!e.archived||needsScrapControl(e)?`<button id="newControl">${needsScrapControl(e)?'Compléter le contrôle de mise au rebut':'+ Enregistrer un contrôle'}</button>`:''}<button class="secondary" id="edit">Modifier la fiche</button><button class="secondary" id="archiveEquipment">${e.pendingArchive?'Poursuivre la demande':e.archived?'Désarchiver':'Archiver'}</button></div>${archiveHistoryHtml(e)}${e.scheduledControl&&!e.archived?`<section class="archive-info"><h3>Contrôle à réaliser</h3><p>Créé automatiquement à l’ajout de l’équipement · Date prévue : <b>${fmt(e.scheduledControl.date)}</b></p><p>Aucun résultat enregistré. Utilisez « Enregistrer un contrôle » pour le réaliser.</p></section>`:''}<h3>Historique des contrôles réglementaires</h3>${[...e.controls].sort((a,b)=>b.date.localeCompare(a.date)||b.created-a.created).map(c=>`<article class="history"><b>${fmt(c.date)} · ${esc(c.result)}</b><small class="report-reference">Rapport ${esc(c.reportId)}</small><p>Intervenant : ${esc(c.intervenant)}<br>${esc(c.observations).replace(/\n/g,'<br>')}</p><div class="actions">${c.attachment?`<a href="${esc(c.attachment.url)}" download="${esc(c.attachment.name)}">Télécharger : ${esc(c.attachment.name)}</a>`:''}<button class="secondary" data-control-pdf="${c.id}">Télécharger le PDF</button><button class="secondary" data-report="${c.id}">Compte rendu / PDF</button></div></article>`).join('')||`<p>Aucun contrôle réalisé enregistré. ${e.firstControlDate?'Premier contrôle à faire le '+fmt(due(e))+'.':'La date du premier contrôle reste à définir.'}</p>`}</div><section id="equipmentComments" hidden><h3>Commentaires de l’équipement</h3><form id="commentsForm"><label>Commentaire modifiable<textarea name="comments" maxlength="5000" rows="7">${esc(e.comments)}</textarea></label><p id="commentsError" class="error" role="alert"></p><p id="commentsSaved" role="status"></p><button>Enregistrer le commentaire</button></form></section>`;bindEquipmentComments(id);$('#archiveEquipment').onclick=()=>openArchive();if($('#newControl'))$('#newControl').onclick=()=>{controlContext=needsScrapControl(e)?'scrapCompletion':'normal';$('#controlForm').reset();if(controlContext==='scrapCompletion')$('#controlForm').elements.result.value='Mauvais état — à jeter';$('#controlError').textContent='';$('#controlForm').elements.date.value=today();$('#control').showModal()};$('#edit').onclick=()=>{$('#detail').close();edit(id)};if(!$('#detail').open)$('#detail').showModal()}
$('#controlForm').onsubmit=async ev=>{ev.preventDefault();try{const c=await readControl(ev.target,true),next=copyData(data);const equipment=next.equipment.find(e=>e.id===selected);if(equipment.archived&&!(controlContext==='scrapCompletion'&&needsScrapControl(equipment)))throw Error('Désarchivez cet équipement avant d’enregistrer un contrôle.');if(controlContext==='scrapCompletion'&&c.result!=='Mauvais état — à jeter')throw Error('Le résultat d’une mise au rebut doit être « Mauvais état — à jeter ».');if(!latest(equipment)||c.date>latest(equipment).date)c.plannedDate=due(equipment);c.equipmentSnapshot=equipmentSnapshot(equipment);equipment.controls.push(c);if(controlContext==='scrapCompletion')lastArchive(equipment).controlId=c.id;equipment.scheduledControl=null;if(save(next)){$('#control').close();showDetail(selected);$('#message').textContent=`Contrôle enregistré${memoryOnly?' pour cette session uniquement':''}.`}else{$('#controlError').textContent=$('#message').textContent}}catch(e){$('#controlError').textContent=e.message}};
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.hasAttribute('data-add-verifier')){const name=prompt('Nom du vérificateur :');if(name?.trim()){const value=name.trim();if(value.length>160)return;const next=copyData(data),existing=next.verifiers.find(n=>normalize(n)===normalize(value));if(!existing)next.verifiers.push(value);if(save(next))b.closest('label').querySelector('[name=intervenant]').value=existing||value}}if(b.dataset.close)$('#'+b.dataset.close).close();if(b.dataset.open)showDetail(b.dataset.open);if(b.dataset.deadline){if($('#kpiListDialog').open)$('#kpiListDialog').close();openDeadline(b.dataset.deadline);}if(b.dataset.report)report(b.dataset.report);if(b.dataset.archiveReport)archiveDocument(b.dataset.archiveReport);if(b.dataset.controlPdf)downloadControlPdf(b.dataset.controlPdf)});
