async function signedFile(file){if(!file?.size)throw Error('Joignez le document signé.');if(file.size>1024*1024)throw Error('Le document signé dépasse 1 Mo.');if(!['application/pdf','image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Le document signé doit être un PDF ou une image PNG, JPEG ou WebP.');const url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Lecture du document impossible.'));reader.readAsDataURL(file)});return {name:file.name,type:file.type,url}}
async function approveArchive(ev){ev.preventDefault();const button=$('#validateArchive');button.disabled=true;try{const equipment=data.equipment.find(e=>e.id===selected),a=equipment.pendingArchive,f=new FormData(ev.target);if(!a?.generated)throw Error('Générez d’abord le document à signer.');if(!f.get('approver').trim()||!f.get('confirmed'))throw Error('Renseignez l’approbateur et confirmez la présence de la signature.');if(f.get('approvalDate')<a.date||f.get('approvalDate')>today())throw Error('Vérifiez la date d’approbation.');const attachment=await signedFile(f.get('signedAttachment'));const control=a.type==='restore'||a.reason==='Mis au rebut'?await readControl(ev.target,true):null;if(a.reason==='Mis au rebut'&&control.result!=='Mauvais état — à jeter')throw Error('Le résultat d’une mise au rebut doit être « Mauvais état — à jeter ».');if(a.type==='restore'&&control&&control.date<a.date)throw Error('Le contrôle de désarchivage doit être daté à partir de la demande.');if(a.reason==='Mis au rebut'&&control.date>f.get('approvalDate'))throw Error('Le contrôle de mise au rebut doit être réalisé au plus tard à la date d’approbation.');const next=copyData(data);const e=next.equipment.find(e=>e.id===selected);if(e.pendingArchive?.id!==a.id)throw Error('La demande a changé. Rouvrez la fiche.');e.archiveHistory.push({...a,approver:f.get('approver').trim(),approvalDate:f.get('approvalDate'),signedAttachment:attachment,validated:Date.now(),controlId:control?.id??null});e.archived=a.type==='archive';materialScope=e.archived?'archived':'active';$('#filter').value='';e.pendingArchive=null;if(control){if(!latest(e)||control.date>latest(e).date)control.plannedDate=due(e);control.equipmentSnapshot=equipmentSnapshot(e);e.controls.push(control);e.scheduledControl=null}if(save(next)){$('#archiveDialog').close();showDetail(selected)}}catch(error){$('#archiveError').textContent=error.message}finally{button.disabled=false}}
function attachmentValid(a){return a&&typeof a.name==='string'&&typeof a.url==='string'&&/^data:(application\/pdf|image\/(png|jpeg|webp));base64,[A-Za-z0-9+/=]+$/.test(a.url)}
function archiveDataValid(d){if(!Array.isArray(d?.equipment))return false;const date=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(Date.parse(s));const request=a=>a&&typeof a.id==='string'&&['archive','restore'].includes(a.type)&&typeof a.reason==='string'&&a.reason.trim()&&(a.type!=='archive'||['Équipement perdu','Mis au rebut'].includes(a.reason))&&date(a.date)&&typeof a.requester==='string'&&a.requester.trim()&&typeof a.observations==='string'&&typeof a.created==='number'&&typeof a.generated==='boolean'&&a.snapshot&&['identifier','serialNumber','designation','category','location','sector','team','owner','assignment'].every(k=>typeof a.snapshot[k]==='string');return d.equipment.every(e=>{if(e.archived!==undefined&&typeof e.archived!=='boolean')return false;if(e.pendingArchive!=null&&(!request(e.pendingArchive)||e.pendingArchive.type!==(e.archived?'restore':'archive')))return false;if(e.archiveHistory!==undefined&&(!Array.isArray(e.archiveHistory)||!e.archiveHistory.every(a=>request(a)&&a.generated&&date(a.approvalDate)&&a.approvalDate>=a.date&&typeof a.approver==='string'&&a.approver.trim()&&typeof a.validated==='number'&&attachmentValid(a.signedAttachment)&&(a.type!=='restore'||e.controls?.some(c=>c.id===a.controlId)))))return false;return !e.archived||e.archiveHistory?.at(-1)?.type==='archive'})}

render();
